  <thead>
    <tr>
      <th>序号</th>
      <th>主图</th>
      <th>图片比例</th>
      <th>文字卖点（默认空，可选填）</th>
      <th>场景</th>
      <th class="prompt-cell">提示词（系统自动生成，只读）</th>
