  syncPrompt(i);
}}

function onTextSellingPointsChange(el) {{
  const i = parseInt(el.dataset.idx);
  ROWS[i].text_selling_points = el.value;
  syncPrompt(i);
}}

function onSceneChange(el) {{
  const i = parseInt(el.dataset.idx);
